-- Wine geography: Country → Region → Appellation (+ subregion). Generated by scripts/wine-geography.py.
create table if not exists wine_regions (
  id text primary key, country text not null, name text not null, aliases text[] not null default '{}',
  lat double precision, lon double precision);
alter table wine_regions enable row level security;
drop policy if exists read_all on wine_regions;
create policy read_all on wine_regions for select to anon, authenticated using (true);
grant select on wine_regions to anon, authenticated;
alter table appellations add column if not exists subregion text;

on conflict (id) do update set country = excluded.country, name = excluded.name, aliases = excluded.aliases, lat = excluded.lat, lon = excluded.lon;

on conflict (id) do update set name = excluded.name, region = excluded.region, country = excluded.country, subregion = excluded.subregion, aliases = excluded.aliases, lat = excluded.lat, lon = excluded.lon;

update appellations set subregion = 'Médoc' where id in ('medoc', 'haut-medoc', 'margaux', 'pauillac', 'saint-julien', 'saint-estephe', 'listrac-medoc', 'moulis');
update appellations set subregion = 'Graves & Sauternais' where id in ('graves', 'pessac-leognan', 'sauternes', 'barsac');
update appellations set subregion = 'Libournais' where id in ('saint-emilion', 'saint-emilion-grand-cru', 'saint-emilion-satellites', 'pomerol', 'lalande-de-pomerol', 'fronsac', 'canon-fronsac');
update appellations set subregion = 'Entre-Deux-Mers' where id in ('entre-deux-mers');
update appellations set subregion = 'Côtes de Bordeaux' where id in ('blaye', 'cadillac', 'castillon', 'cotes-de-bourg', 'francs');
update appellations set subregion = 'Côte de Nuits' where id in ('chambolle-musigny', 'cote-de-nuits-villages', 'gevrey-chambertin', 'morey-saint-denis', 'nuits-saint-georges', 'vosne-romanee', 'vougeot');
update appellations set subregion = 'Côte de Beaune' where id in ('beaune', 'chassagne-montrachet', 'corton', 'meursault', 'pommard', 'puligny-montrachet', 'santenay', 'volnay');
update appellations set subregion = 'Chablis' where id in ('chablis', 'chablis-grand-cru');
update appellations set subregion = 'Côte Chalonnaise' where id in ('mercurey');
update appellations set subregion = 'Mâconnais' where id in ('macon', 'pouilly-fuisse');
update appellations set subregion = 'Rhône Nord' where id in ('condrieu', 'cornas', 'cote-rotie', 'crozes-hermitage', 'hermitage', 'saint-joseph');
update appellations set subregion = 'Rhône Sud' where id in ('chateauneuf-du-pape', 'gigondas', 'lirac', 'rasteau', 'tavel', 'vacqueyras', 'cotes-du-rhone-villages');
update appellations set subregion = 'Langhe' where id in ('barolo', 'barbaresco', 'barbera-d-alba', 'dolcetto-d-alba', 'langhe', 'nebbiolo-d-alba');
update appellations set subregion = 'Roero' where id in ('roero');
update appellations set subregion = 'Monferrato' where id in ('barbera-d-asti', 'moscato-d-asti', 'gavi');
update appellations set subregion = 'Chianti' where id in ('chianti', 'chianti-classico');
update appellations set subregion = 'Montalcino' where id in ('brunello-di-montalcino', 'rosso-di-montalcino');
update appellations set subregion = 'Montepulciano' where id in ('vino-nobile-di-montepulciano');
update appellations set subregion = 'Costa Toscana' where id in ('bolgheri');
update appellations set subregion = 'Maremma' where id in ('maremma');
update appellations set subregion = 'Saar' where id in ('saar');
update appellations set subregion = 'Ruwer' where id in ('ruwer');
update appellations set subregion = 'Rioja Alta' where id in ('rioja-alta');
update appellations set subregion = 'Rioja Alavesa' where id in ('rioja-alavesa');
update appellations set subregion = 'Rioja Oriental' where id in ('rioja-oriental');
update appellations set subregion = 'Napa Valley' where id in ('calistoga', 'howell-mountain', 'los-carneros', 'oakville', 'rutherford', 'st-helena', 'stags-leap-district');
update appellations set subregion = 'North Coast' where id in ('napa-valley');
update appellations set region = 'California' where country = 'US' and region = 'Napa Valley';
update wines set region = 'California' where country = 'US' and region = 'Napa Valley';
-- Wines whose appellation is now known get linked (the wines_origin trigger sets name, region and country)
update wines set appellation = appellation where appellation_id is null and match_appellation(appellation) is not null;
